    (* [comment removed for export] *)
    Definition put_drain_rec_post : machine_state -> Prop := fun ms' =>
      exists (t0' t1' a4' a5' a6' a7' : word) m1,
        ms' = MS (mkR (wz 0x5455c) (Z_to_bv 64 (bv_unsigned sp + -2208)) gp tp t0' t1' t2 (wz (AINST + OI_Q)) (wz (TH + OT_TQ)) (wz (AINST + OI_Q)) (wz qmin)
                      (wz (TH + OT_CACHE)) (Z_to_bv 64 (bv_unsigned sp + -2128)) a4' a5' a6' a7'
                      (wz size) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz (TH + OT_CACHE)) (wz (U + -16)) (wz qcache) s7 s8 s9 s10 s11 t3 t4 t5 t6)
                 F (Z_to_bv 64 0x51f2c) fc None m1 (seg_rom bsegs)
        /\ DMEM m1 256
        /\ rw_cells bsegs m1 (bv_unsigned sp + -2208) (put_frame sp s6 U TH)
        /\ rw_cells bsegs m1 (bv_unsigned sp + -2128) [C8 (wz (bv_unsigned sp + -2128 + 16)); C8 (wz (Z.of_nat (length T)))]
        /\ u64arr bsegs m1 (bv_unsigned sp + -2128 + 16) (map wz T ++ rest)
        /\ rw_cells bsegs m1 (bv_unsigned sp + -72) [C8 sp]
        /\ rw_cells bsegs m1 (bv_unsigned sp + -64) [CB 8 jk; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 ra0].

